-- دليل الخدمات الكامل (طلب المالك 2026-08-09: «كامل متكامل لكل خدماتنا
-- بالتفصيل الدقيق»): لكل خدمة من الـ٣٧ — عرض البيع، لمن، المدة، المخرجات،
-- خطوات التنفيذ، ما نحتاجه من العميل، ومؤشرات النجاح. مصدر واحد يغذي
-- دليل المبيعات في المسار وقاعدة المعرفة (المساعد يجيب عنها) معاً.

create table public.service_guides (
  service_id uuid primary key references public.services_catalog (id) on delete cascade,
  pitch_ar text not null,
  ideal_for_ar text not null,
  duration_ar text not null,
  deliverables jsonb not null default '[]',
  steps jsonb not null default '[]',
  client_inputs jsonb not null default '[]',
  kpis jsonb not null default '[]',
  kb_article_id uuid references public.kb_articles (id) on delete set null,
  updated_at timestamptz not null default now()
);

comment on table public.service_guides is
  'التفصيل البيعي والتنفيذي لكل خدمة — يُعرض في دليل المبيعات ويتزامن تلقائياً مع قاعدة المعرفة (دليل الخدمات، داخلي). المدد تقديرات لا التزام تعاقدي.';

alter table public.service_guides enable row level security;
grant select, insert, update, delete on public.service_guides to authenticated, service_role;
create policy "service guides: team reads" on public.service_guides
  for select to authenticated using (public.is_team());
create policy "service guides: leads manage" on public.service_guides
  for all to authenticated
  using (public.is_admin() or public.is_strategist_plus())
  with check (public.is_admin() or public.is_strategist_plus());

-- المزامنة مع المعرفة: الدليل مقال داخلي يجيب عنه المساعد — مصدر واحد
create or replace function public.service_guide_sync()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_name text; v_body text; v_kb uuid;
begin
  select name_ar into v_name from public.services_catalog where id = new.service_id;
  v_body := '## ما هي؟' || E'\n' || new.pitch_ar
    || E'\n\n## لمن؟\n' || new.ideal_for_ar
    || E'\n\n## المدة المعتادة\n' || new.duration_ar || ' (تقدير لا التزام — الالتزام في النطاق وعرض السعر)'
    || E'\n\n## المخرجات\n'
    || (select coalesce(string_agg('- ' || x, E'\n'), '') from jsonb_array_elements_text(new.deliverables) x)
    || E'\n\n## خطوات التنفيذ\n'
    || (select coalesce(string_agg(t.ord::text || '. **' || (t.s->>'title') || '** — ' || coalesce(t.s->>'desc', ''), E'\n' order by t.ord), '')
        from jsonb_array_elements(new.steps) with ordinality as t(s, ord))
    || E'\n\n## ما نحتاجه من العميل\n'
    || (select coalesce(string_agg('- ' || x, E'\n'), '') from jsonb_array_elements_text(new.client_inputs) x)
    || E'\n\n## كيف نقيس النجاح؟\n'
    || (select coalesce(string_agg('- ' || x, E'\n'), '') from jsonb_array_elements_text(new.kpis) x);

  if new.kb_article_id is null then
    insert into public.kb_articles (title, body_md, category, audience, published)
    values ('دليل الخدمة: ' || v_name, v_body, 'دليل الخدمات', 'internal', true)
    returning id into v_kb;
    new.kb_article_id := v_kb;
  else
    update public.kb_articles
      set title = 'دليل الخدمة: ' || v_name, body_md = v_body,
          published = true, indexed_at = null
      where id = new.kb_article_id;
  end if;
  new.updated_at := now();
  return new;
end;
$$;

create trigger service_guides_sync
  before insert or update on public.service_guides
  for each row execute function public.service_guide_sync();

-- =============================================================================
-- البذور — ٣٧ خدمة بالتفصيل. أسلوب ثابت: بيع صادق بلا مبالغة، مدد واقعية
-- كنطاقات، مدخلات عميل ملموسة، ومؤشرات قابلة للقياس.
-- =============================================================================
create or replace function public._sg(
  p_slug text, p_pitch text, p_ideal text, p_duration text,
  p_deliverables jsonb, p_steps jsonb, p_inputs jsonb, p_kpis jsonb
) returns void language plpgsql as $$
begin
  insert into public.service_guides
    (service_id, pitch_ar, ideal_for_ar, duration_ar, deliverables, steps, client_inputs, kpis)
  select id, p_pitch, p_ideal, p_duration, p_deliverables, p_steps, p_inputs, p_kpis
  from public.services_catalog where slug = p_slug
  on conflict (service_id) do nothing;
end;
$$;

-- ---------- الذكاء الاصطناعي والأتمتة ----------------------------------------
select public._sg('ai-agents',
 'نبني وكيل ذكاء اصطناعي متخصصاً في عمل واحد يتقنه: يرد على عملائك، يؤهل طلباتك، يلخص تقاريرك، أو ينفذ مهمة تشغيلية كاملة — يعمل ٢٤/٧ بجودة ثابتة ويتحسن بالمراجعة.',
 'منشأة لديها مهمة متكررة تستهلك ساعات بشرية يومياً (رد، فرز، تلخيص، إدخال بيانات) وتريد تحريرها دون توظيف إضافي.',
 '٤–٨ أسابيع بحسب تعقيد المهمة ومصادر البيانات',
 '["وكيل ذكاء يعمل في بيئة العميل أو سحابياً بصلاحيات محدودة موثقة","تكامل مع أدواتك القائمة (بريد، واتساب، CRM، جداول)","لوحة مراقبة أداء الوكيل وسجلات قراراته","حواجز أمان: حدود صلاحيات، مراجعة بشرية للحالات الحساسة","تدريب فريقك على التشغيل والتصحيح","شهر دعم وضبط بعد الإطلاق"]'::jsonb,
 '[{"title":"تدقيق المهمة","desc":"نجلس مع من ينفذها اليوم ونوثق كل حالة وقرار واستثناء — الوكيل الجيد يبدأ بفهم دقيق لا بنموذج كبير"},{"title":"تصميم الحواجز","desc":"ما يقرره الوكيل وحده وما يرفعه لبشري — قرار يُعتمد منك كتابةً قبل أي بناء"},{"title":"البناء والربط","desc":"بناء الوكيل وربطه بمصادر بياناتك وأدواتك بصلاحيات الحد الأدنى"},{"title":"اختبار محاكاة","desc":"نشغله على حالات تاريخية حقيقية ونقيس دقته قبل أن يلمس عميلاً واحداً"},{"title":"إطلاق تدريجي","desc":"نسبة صغيرة من الحالات أولاً ثم التوسع مع ثبات الجودة"},{"title":"شهر الضبط","desc":"مراجعة أسبوعية للسجلات وتصحيح الانحرافات وتوسيع التغطية"}]'::jsonb,
 '["وصف دقيق للمهمة ومن ينفذها اليوم (جلسة عمل)","وصول للأدوات والبيانات المعنية بصلاحيات محدودة","عينة حالات تاريخية للاختبار","شخص مرجعي يرد على أسئلتنا خلال البناء"]'::jsonb,
 '["نسبة الحالات التي ينهيها الوكيل دون تدخل بشري","دقة القرارات مقابل المراجعة البشرية (عينة أسبوعية)","الساعات البشرية الموفرة شهرياً","زمن الاستجابة من الطلب إلى الإنجاز"]'::jsonb);

select public._sg('workflow-automation',
 'نرسم عملياتك المتكررة ثم نؤتمتها من طرف لطرف: من وصول الطلب إلى إقفاله — بلا نسخ يدوي بين الأدوات ولا خطوات منسية.',
 'منشأة تدير عملياتها بين أدوات متفرقة (بريد، واتساب، جداول، نظام محاسبة) ويضيع وقتها في النقل اليدوي بينها.',
 '٣–٦ أسابيع للعملية الأولى، وأسرع لما بعدها',
 '["خريطة العملية الحالية والمقترحة (قبل/بعد) معتمدة منك","أتمتة مبنية على أدوات موثوقة بحساباتك أنت (لا احتكار)","معالجة الاستثناءات: ما يتعثر يصل تنبيهاً واضحاً لا يضيع صامتاً","توثيق تشغيلي مختصر يفهمه فريقك","تدريب + أسبوعا مراقبة بعد التشغيل"]'::jsonb,
 '[{"title":"رسم العملية","desc":"نوثق الخطوات الفعلية اليوم بمن ينفذها وأين تتعثر — الأتمتة على عملية مكسورة تسرّع الكسر"},{"title":"إعادة التصميم","desc":"نحذف الخطوات الميتة ونقترح المسار الأمثل ونعتمده منك قبل البناء"},{"title":"البناء","desc":"ربط الأدوات وبناء المسار الآلي بحساباتك وصلاحيات محدودة"},{"title":"اختبار الحالات الحرجة","desc":"نجرب النجاح والفشل والاستثناء — العملية القوية تُقاس عند التعثر"},{"title":"تشغيل ومراقبة","desc":"تشغيل فعلي بمراقبة أسبوعين وضبط ما يظهر"}]'::jsonb,
 '["جلسة توثيق مع منفذي العملية الحاليين","حسابات الأدوات المستخدمة (تُدار عبر مدير كلمات مرور لا رسائل)","اعتماد خريطة العملية الجديدة قبل البناء"]'::jsonb,
 '["زمن دورة العملية من البداية للإقفال (قبل/بعد)","عدد التدخلات اليدوية لكل عملية","نسبة الحالات المتعثرة وسرعة اكتشافها","ساعات العمل الموفرة شهرياً"]'::jsonb);

select public._sg('chatbots',
 'روبوت محادثة يجيب عملاءك فوراً على واتساب أو موقعك من معرفة منشأتك المعتمدة فقط — يرد بدقة، يؤهل المهتم، ويسلّم البشري ما لا يعرفه بدل التخمين.',
 'منشأة تصلها أسئلة متكررة كثيرة (أسعار، مواعيد, تغطية، حجوزات) ويتأخر ردها البشري أو يستهلك فريقها.',
 '٣–٥ أسابيع شاملة بناء قاعدة المعرفة',
 '["روبوت محادثة عربي أولاً على قناتك المختارة (واتساب/الموقع/الاثنين)","قاعدة معرفة معتمدة منك يجيب منها حصراً — لا اختلاق","مسار تسليم بشري ذكي للحالات الخارجة عن معرفته","التقاط بيانات المهتمين وتسليمها لنظامك","لوحة: الأسئلة، نسب الإجابة، وما عجز عنه (فرص تحسين)","تحديث شهري لقاعدة المعرفة أول ٣ أشهر"]'::jsonb,
 '[{"title":"حصر الأسئلة الحقيقية","desc":"نجمع أسئلة عملائك الفعلية من قنواتك آخر ٣ أشهر — لا نخمن ما يسألون"},{"title":"بناء المعرفة","desc":"صياغة الإجابات المعتمدة منك بلغة علامتك — أنت توقع على كل إجابة"},{"title":"البناء والربط","desc":"بناء الروبوت وربطه بقناتك وتجهيز مسار التسليم البشري"},{"title":"اختبار الحدود","desc":"نهاجمه بأسئلة خارج معرفته ونتأكد أنه يسلّم لا يخترع"},{"title":"إطلاق ومراقبة","desc":"تشغيل فعلي مع مراجعة أسبوعية لما عجز عنه وتغذية المعرفة"}]'::jsonb,
 '["تصدير محادثات/أسئلة العملاء الفعلية","اعتماد الإجابات الرسمية (جلسة مراجعة)","وصول قناة التواصل (رقم واتساب الأعمال أو الموقع)"]'::jsonb,
 '["نسبة الأسئلة المجابة آلياً بدقة","زمن أول رد (من ساعات إلى ثوانٍ)","عدد المهتمين الملتقطين شهرياً","رضا العملاء عن الردود (تقييم بعد المحادثة)"]'::jsonb);

select public._sg('geo',
 'محركات البحث الذكية (ChatGPT، Gemini، Perplexity) صارت تجيب عملاءك مباشرة — نجهز محتواك وحضورك الرقمي لتكون أنت الجواب الذي تقترحه حين يسألون عن مجالك.',
 'منشأة يبحث عملاؤها عن خدماتها بالسؤال المباشر للذكاء، وتريد أن تُذكر في إجاباته قبل منافسيها.',
 'شهران للتأسيس ثم دورات شهرية',
 '["تدقيق حضورك الحالي في إجابات محركات الذكاء (أين تُذكر وأين تغيب)","إعادة هيكلة محتواك بصيغ يفهمها الذكاء ويستشهد بها","بيانات منظمة (Schema) وصفحات مرجعية تجيب أسئلة مجالك مباشرة","بناء إشارات الثقة: ذكر في مصادر يعتمدها الذكاء","تقرير شهري: حضورك في الإجابات مقابل المنافسين"]'::jsonb,
 '[{"title":"قياس خط الأساس","desc":"نسأل محركات الذكاء أسئلة عملائك الفعلية ونوثق من يُذكر اليوم — أنت أم منافسوك"},{"title":"فجوات المحتوى","desc":"تحديد الأسئلة التي لا يملك محتواك جواباً مرجعياً لها"},{"title":"البناء","desc":"صفحات إجابة مرجعية وبيانات منظمة وأسئلة شائعة بصياغة يقتبسها الذكاء"},{"title":"إشارات الثقة","desc":"حضور في المصادر والأدلة التي تتغذى منها النماذج"},{"title":"دورة شهرية","desc":"إعادة القياس وتوسيع التغطية سؤالاً بعد سؤال"}]'::jsonb,
 '["وصول تحرير الموقع","قائمة أسئلة عملائك الأكثر تكراراً","اعتماد المحتوى المرجعي قبل النشر"]'::jsonb,
 '["نسبة أسئلة مجالك التي تُذكر فيها (نقيسها شهرياً بنفس الأسئلة)","الزيارات القادمة من محركات الذكاء","جودة الذكر: توصية مباشرة أم إشارة عابرة"]'::jsonb);

select public._sg('predictive-analytics',
 'بياناتك التاريخية تعرف مستقبلك: نبني نماذج تتوقع مبيعاتك، عملاءك المعرضين للمغادرة، ومخزونك المطلوب — فتقرر بالأرقام قبل أن يحدث الشيء لا بعده.',
 'منشأة لديها بيانات تشغيل سنة فأكثر (مبيعات، عملاء، مخزون) وتتخذ قراراتها اليوم بالحدس.',
 '٦–١٠ أسابيع بحسب جاهزية البيانات',
 '["تدقيق جاهزية بياناتك وخطة معالجة فجواتها","نموذج تنبؤي لهدف واحد محدد (مبيعات/مغادرة/طلب) بدقة موثقة","لوحة قرار تعرض التوقع بلغة عمل لا إحصاء","تشغيل دوري آلي للنموذج على بياناتك الجديدة","جلسة تفسير شهرية أول ربع: ماذا يقول النموذج وماذا نفعل"]'::jsonb,
 '[{"title":"سؤال العمل أولاً","desc":"نحدد القرار الذي سيتغير بالتوقع — نموذج بلا قرار خلفه زينة"},{"title":"تدقيق البيانات","desc":"فحص الاكتمال والجودة — ونصارحك إن كانت بياناتك لا تكفي بعد"},{"title":"بناء النموذج","desc":"تجارب على تاريخك الفعلي واختيار الأدق باختبار عادل"},{"title":"لوحة القرار","desc":"التوقعات بصيغة إجراء: من تتصل عليه، كم تطلب، متى تتحرك"},{"title":"التشغيل الدوري","desc":"النموذج يتحدث آلياً مع بياناتك الجديدة ونراجع دقته شهرياً"}]'::jsonb,
 '["تصدير بياناتك التاريخية (سنة فأكثر)","تحديد القرار المستهدف مع صاحبه","شخص تقني/بيانات للتنسيق إن وجد"]'::jsonb,
 '["دقة التوقع مقابل الواقع (نقيسها كل شهر)","أثر القرارات المبنية عليه (مبيعات محفوظة، مخزون موفر)","نسبة استخدام الفريق للوحة فعلياً"]'::jsonb);

-- ---------- التسويق الأدائي والإعلانات ----------------------------------------
select public._sg('paid-social',
 'حملات مدفوعة على سناب وتيك توك وإنستغرام وإكس تُبنى على رسالة مختبرة وجمهور مدروس — بميزانية محمية بسقوف وقياس صادق يخبرك ماذا كسبت مقابل كل ريال.',
 'منشأة تريد عملاء أو مبيعات الآن من المنصات التي يقضي جمهورها السعودي يومه فيها.',
 'أسبوعان للتأسيس ثم إدارة شهرية',
 '["استراتيجية قنوات: أي منصة ولماذا وبأي حصة ميزانية","حسابات إعلانية مهيأة باسمك أنت (ملكيتك دائماً) مع بكسل وقياس تحويل","٣ زوايا رسائل تُختبر أول أسبوعين قبل ضخ الميزانية","تصاميم إعلانية شهرية بهوية علامتك","تقرير شهري بلغة عمل: تكلفة العميل، العائد، وقرارات الشهر القادم"]'::jsonb,
 '[{"title":"جلسة التأسيس","desc":"الجمهور، العرض، الميزانية، وتعريف التحويل الذي يهمك فعلاً — لا نطلق قبل اتفاق مكتوب عليها"},{"title":"البنية والقياس","desc":"حسابات باسمك، بكسل يعمل مثبتاً، UTM موحدة — فحص إطلاق إلزامي عندنا"},{"title":"اختبار الرسائل","desc":"٣ زوايا بميزانية صغيرة أسبوعين — الأرقام تختار لا الذوق"},{"title":"التوسع المنضبط","desc":"ضخ الميزانية في الفائز مع سقوف يومية تحمي محفظتك"},{"title":"الدورة الشهرية","desc":"تقرير وقرارات: نوقف الخاسر ونجرب زاوية جديدة كل دورة"}]'::jsonb,
 '["وصول/إنشاء الحسابات الإعلانية والصفحات (بملكيتك)","الميزانية الشهرية وسقفها","اعتماد الرسائل والتصاميم (خلال يومي عمل ليبقى الإيقاع)","تركيب البكسل على موقعك أو وصول لتركيبه"]'::jsonb,
 '["تكلفة اكتساب العميل (CAC) واتجاهها شهرياً","العائد على الإنفاق الإعلاني (ROAS)","معدل التحويل من نقرة إلى إجراء","حصة الإنفاق على الرسائل الفائزة (كفاءة التعلم)"]'::jsonb);

select public._sg('google-ads',
 'نلتقط عميلك لحظة بحثه عنك: حملات بحث وأداء على جوجل بكلمات مدروسة عربياً، وصفحات هبوط تكمل الوعد — فلا تدفع لنقرات تتسرب.',
 'منشأة يبحث عملاؤها عن خدمتها نصاً في جوجل (خدمات، عيادات، مقاولات، متاجر) وتريد طلبات جاهزة النية.',
 'أسبوعان للتأسيس ثم إدارة شهرية',
 '["بحث كلمات عربي حقيقي: ماذا يكتب عميلك فعلاً (لا ترجمات)","حساب إعلاني مهيأ باسمك مع قياس تحويل مثبت","حملات بحث + كلمات سالبة تمنع الهدر من اليوم الأول","إعلانات مكتوبة تختبر أكثر من وعد","تقرير شهري: تكلفة الطلب، جودة الطلبات، وقرارات التالي"]'::jsonb,
 '[{"title":"بحث الكلمات","desc":"نستخرج ما يكتبه عميلك السعودي حرفياً بأدوات البيانات لا بالتخمين — العربي له مزاجه"},{"title":"البنية النظيفة","desc":"مجموعات مرتبة بكلمات سالبة من البداية — الهدر يُمنع لا يُكتشف"},{"title":"القياس قبل الإطلاق","desc":"تحويل مثبت يعمل (اتصال، نموذج، شراء) — فحص إطلاقنا الإلزامي"},{"title":"الإطلاق والتحسين الأسبوعي","desc":"مراجعة مصطلحات البحث الفعلية أسبوعياً: نضيف السالب ونرفع الرابح"},{"title":"الدورة الشهرية","desc":"تقرير بلغة عمل وقرارات موثقة للشهر القادم"}]'::jsonb,
 '["وصول/إنشاء حساب Google Ads بملكيتك","الميزانية الشهرية","تعريف الطلب الناجح (اتصال؟ نموذج؟ بيع؟)","صفحة هبوط أو موافقة على بنائها"]'::jsonb,
 '["تكلفة الطلب الواحد (CPL) واتجاهها","نسبة الطلبات الجادة من الإجمالي (نتتبعها معك)","نقاط جودة الكلمات الرئيسية","نسبة الإنفاق المهدور الممنوع بالكلمات السالبة"]'::jsonb);

select public._sg('programmatic',
 'إعلانات آلية عبر شبكات العرض والفيديو والشاشات تصل جمهورك أينما تصفح — بشراء مبرمج يستهدف بدقة ويُقاس بشفافية بدل حجوزات المجاملات.',
 'علامة تريد وصولاً واسعاً مدروساً (وعي، إطلاق، موسم) بميزانية تتجاوز حدود المنصات الاجتماعية وحدها.',
 '٣ أسابيع للتأسيس ثم إدارة شهرية',
 '["خطة وصول: الشبكات والصيغ والجمهور والتكرار المضبوط","تهيئة منصة الشراء البرمجي بحساب يخصك","مواد إعلانية بمقاسات الشبكات المختارة","حماية العلامة: قوائم استبعاد المواقع والمحتوى غير اللائق","تقرير شهري: وصول حقيقي، تكرار، تكلفة الألف، وأثر على البحث المباشر"]'::jsonb,
 '[{"title":"خطة الوصول","desc":"من نريد أن يرانا وكم مرة وأين — التكرار المنفلت يحرق ولا يبني"},{"title":"التهيئة والحماية","desc":"إعداد الحساب وقوائم الاستبعاد — إعلانك لا يظهر بجوار ما يسيء لك"},{"title":"المواد","desc":"تكييف هويتك لمقاسات الشبكات مع رسالة واحدة واضحة"},{"title":"الإطلاق المتدرج","desc":"شبكة فشبكة مع مراقبة جودة المواضع فعلياً"},{"title":"الدورة الشهرية","desc":"تنظيف المواضع الضعيفة وتركيز الميزانية في الفعال"}]'::jsonb,
 '["الميزانية وحدود الحملة الزمنية","اعتماد قوائم الأمان (ما لا تريد الظهور بجواره)","هويتك البصرية أو تفويضنا ببنائها"]'::jsonb,
 '["الوصول الفعلي ونسبة الظهور للبشر (لا الروبوتات)","تكلفة الألف ظهور مقابل السوق","التكرار المتوسط ضمن النطاق المتفق","أثر الحملة على البحث المباشر عن اسمك"]'::jsonb);

select public._sg('cro',
 'زوارك موجودون لكنهم لا يشترون؟ نحسّن معدل التحويل بمنهج علمي: نراقب سلوكهم الفعلي، نجد نقاط التسرب، ونختبر الحلول اختباراً عادلاً — فترتفع مبيعاتك من نفس الزيارات.',
 'موقع أو متجر يستقبل زيارات معقولة (٣٠٠+ أسبوعياً) ومعدل تحويله لا يرضيك — التحسين قبل ضخ إعلانات أوفر من ضخها على صفحة مسربة.',
 'شهر للتشخيص الأول ثم دورات اختبار شهرية',
 '["تشخيص كامل: تسجيلات سلوك، خرائط حرارة، وقمع التحويل رقمياً","قائمة فرضيات مرتبة بالأثر المتوقع وسهولة التنفيذ","اختبارات A/B تُدار بأصول إحصائية (لا استنتاج قبل الدلالة)","تنفيذ التحسينات الرابحة على موقعك","تقرير شهري: ما اختبرنا، ما ربح، وأثره بالريال"]'::jsonb,
 '[{"title":"القياس الصادق","desc":"تركيب أدوات السلوك وقمع محدد — أين يدخلون وأين يسقطون بالضبط"},{"title":"التشخيص","desc":"مشاهدة جلسات حقيقية وتحليل نقاط التسرب — البيانات تصف والمشاهدة تفسر"},{"title":"الفرضيات","desc":"قائمة مرتبة: كل فرضية بسبب مرصود وأثر متوقع"},{"title":"الاختبار العادل","desc":"نسختان تتنافسان على زوار حقيقيين حتى الدلالة الإحصائية"},{"title":"التثبيت والتكرار","desc":"الرابح يُثبّت والدورة تعيد نفسها على الفرضية التالية"}]'::jsonb,
 '["وصول تحليلات الموقع وتركيب أدوات القياس","صلاحية تعديل الصفحات (أو مطورك بالتنسيق معنا)","بيانات المبيعات لربط التحسين بالريال"]'::jsonb,
 '["معدل التحويل الكلي واتجاهه","معدل التسرب عند النقاط المشخصة","قيمة الطلب المتوسطة","الإيراد الإضافي المنسوب للاختبارات الرابحة"]'::jsonb);

