select public._sg('seo-audit',
 'فحص شامل لموقعك بعيون جوجل: التقنية والمحتوى والروابط والمنافسون — تستلم تقريراً صريحاً بما يمنع تصدرك وخطة إصلاح مرتبة بالأولوية، تنفذها معنا أو مع من تشاء.',
 'منشأة موقعها لا يظهر في نتائج البحث كما يستحق وتريد تشخيصاً موثوقاً قبل أي إنفاق.',
 'أسبوعان إلى ثلاثة',
 '["تقرير تدقيق تقني: سرعة، فهرسة، أخطاء زحف، جوال، بنية","تحليل محتوى: ما يرتب وما يهدر ومحتوى المنافسين المتصدر","خريطة كلمات عربية بفرصها الحقيقية (حجم بحث ومنافسة)","تدقيق روابط خلفية ومخاطرها","خطة إصلاح مرتبة: أثر كل بند وجهده — تبدأ بالأعلى عائداً"]'::jsonb,
 '[{"title":"الزحف التقني","desc":"فحص آلي كامل للموقع بأدوات الصناعة ثم مراجعة بشرية لما يهم فعلاً"},{"title":"تحليل الترتيب الحالي","desc":"أين تظهر اليوم وبأي كلمات ومن يأخذ مكانك"},{"title":"بحث الكلمات العربي","desc":"ماذا يكتب جمهورك حرفياً — بلهجته لا بفصحى الترجمة"},{"title":"تحليل الفجوة","desc":"مقارنة محتواك بالمتصدرين: ماذا ينقصك لتنافسهم"},{"title":"التقرير والخطة","desc":"جلسة عرض صريحة: الوضع، الفرص، والخطة بالأولوية"}]'::jsonb,
 '["وصول Google Search Console وAnalytics (قراءة)","قائمة كلمات/خدمات تتمنى التصدر بها","أسماء ٣ منافسين تعتبرهم مرجعك"]'::jsonb,
 '["اكتمال التقرير بكل أقسامه خلال المدة","وضوح الخطة: كل بند بأثر وجهد وترتيب","(بعد التنفيذ) تحسن الظهور للكلمات المستهدفة"]'::jsonb);

select public._sg('arabic-seo',
 'السيو العربي صنعة مستقلة: لهجات بحث، مرادفات، ومحتوى يفهمه جوجل وجمهور السعودية معاً — نبني تصدرك شهراً بعد شهر ببناء متين لا حيل تنكسر مع أول تحديث.',
 'منشأة تريد عملاء دائمين من البحث المجاني على المدى الطويل — الاستثمار الذي يتراكم بدل الإيجار الإعلاني.',
 'التزام ٦ أشهر فأكثر — السيو زراعة لا صيد',
 '["استراتيجية كلمات عربية بخريطة محتوى ربع سنوية","إصلاحات تقنية مستمرة على الموقع","محتوى شهري متصدر: مقالات وصفحات خدمة بمعايير التصدر","بناء روابط نظيف من مصادر ذات صلة (لا شراء مزارع)","تقرير شهري: ترتيب، زيارات، وطلبات من البحث"]'::jsonb,
 '[{"title":"الأساس","desc":"تدقيق مصغر وإصلاح المعوقات التقنية الحرجة أولاً — لا بناء على أرض مائلة"},{"title":"خريطة الكلمات","desc":"كلمات بنية شراء وأخرى بنية تعلم — توازن يجلب طلبات اليوم وجمهور الغد"},{"title":"إيقاع المحتوى","desc":"إنتاج شهري ثابت بمعايير التصدر: عمق، هيكلة، وإجابة نية الباحث"},{"title":"بناء السلطة","desc":"روابط وذكر من مواقع يثق بها جوجل في مجالك — بطيء ونظيف"},{"title":"الدورة الشهرية","desc":"قياس الترتيب والزيارات وتحديث الخطة بما تقوله الأرقام"}]'::jsonb,
 '["وصول تحرير الموقع وSearch Console","اعتماد خطة المحتوى ربع السنوية","خبيرك الداخلي لمراجعة دقة المحتوى التخصصي إن وجد"]'::jsonb,
 '["ترتيب الكلمات المستهدفة (نتتبعها أسبوعياً)","الزيارات المجانية من البحث واتجاهها","الطلبات/المبيعات المنسوبة للبحث المجاني","صفحات تتصدر الصفحة الأولى (عدّاد تراكمي)"]'::jsonb);

select public._sg('ai-content',
 'محتوى بحجم يستحيل يدوياً وجودة تحررها عين بشرية: خط إنتاج ذكاء اصطناعي مضبوط بصوت علامتك، يكتب المسودات ويراجعها محررونا قبل أي نشر — الحجم من الآلة والذمة من البشر.',
 'منشأة تحتاج محتوى كثيراً منتظماً (مدونة، أوصاف منتجات، سوشال) وتريده بسرعة الذكاء وثقة المراجعة.',
 'أسبوعان للتأسيس ثم إنتاج شهري',
 '["دليل صوت علامتك للذكاء: نبرة، مفردات، ممنوعات","خط إنتاج مضبوط: توليد ← تحرير بشري ← اعتمادك","الحجم الشهري المتفق (مقالات/أوصاف/منشورات) جاهز النشر","سجل مراجعة موثق لكل قطعة — من حررها ومتى","تحسين النماذج شهرياً بملاحظاتك"]'::jsonb,
 '[{"title":"دليل الصوت","desc":"نستخرج صوت علامتك من موادك الحالية ونحوله تعليمات دقيقة للنماذج"},{"title":"عينة معايرة","desc":"دفعة أولى صغيرة تعتمدها — نضبط عليها قبل خط الإنتاج الكامل"},{"title":"خط الإنتاج","desc":"توليد بالحجم ثم تحرير بشري إلزامي — قاعدتنا: لا ينشر شيء بلا مراجعة موثقة"},{"title":"الاعتماد والنشر","desc":"تعتمد من بوابتك ونجدول النشر"},{"title":"التحسين الشهري","desc":"ملاحظاتك تدخل تعليمات النماذج — الجودة تتراكم"}]'::jsonb,
 '["أمثلة محتوى يمثل صوتك (وما تكرهه أيضاً)","مصادر الحقائق: كتالوج، أسعار، سياسات","اعتماد أسبوعي من بوابتك ليبقى الإيقاع"]'::jsonb,
 '["الحجم المسلّم مقابل المتفق (الانضباط)","نسبة القطع المعتمدة من أول مراجعة","أداء المحتوى: زيارات وتفاعل بحسب القناة","زمن الإنتاج للقطعة مقابل الكتابة اليدوية"]'::jsonb);

select public._sg('copywriting',
 'الكلمة التي تبيع: نصوص إعلانات وصفحات هبوط ورسائل تُكتب على فهم عميلك ولهجة سوقك — كل نص بوعد واضح وسبب للتصديق ودعوة لفعل واحد.',
 'حملة أو صفحة أو علامة تحتاج نصوصاً تحوّل — لا مجرد كلام جميل.',
 'أسبوع إلى ثلاثة بحسب الحجم',
 '["نصوص جاهزة للاستخدام بنسختين للاختبار حيث ينفع","هيكل إقناع موثق: الوعد، الدليل، معالجة الاعتراضات، الدعوة","ملاءمة لهجية لجمهورك (سعودي عام؟ خليجي؟ فصيح؟)","جولتا تعديل ضمن النطاق","ملف مصطلحات علامتك للاستخدام المستقبلي"]'::jsonb,
 '[{"title":"جلسة الفهم","desc":"العرض، الجمهور، الاعتراضات الشائعة، وما يقوله عملاؤك الراضون حرفياً"},{"title":"زوايا الرسالة","desc":"نقترح زوايا إقناع مختلفة وتختار اتجاهاً قبل الكتابة الكاملة"},{"title":"الكتابة","desc":"مسودة كاملة على الهيكل المعتمد بلهجة السوق"},{"title":"المراجعة","desc":"جولتا تعديل بملاحظاتك المجمعة"},{"title":"التسليم","desc":"نصوص نهائية + نسخة اختبار حيث ينفع A/B"}]'::jsonb,
 '["وصف العرض وسعره ونقاط تميزه","أي شهادات/أرقام حقيقية تدعم الوعد","أمثلة نبرة تحبها وأخرى ترفضها"]'::jsonb,
 '["(للإعلانات) نسبة النقر مقابل الحملات السابقة","(للصفحات) معدل التحويل","اعتماد النص خلال جولتي التعديل"]'::jsonb);

