select public._sg('social-management',
 'حضور يومي محترف على منصاتك: تقويم محتوى شهري بهوية ثابتة، نشر منضبط، تفاعل مع جمهورك، وتقرير يفرق بين الجمهور الحقيقي والأرقام الفارغة.',
 'منشأة تعرف أن غيابها عن السوشال يكلفها ثقة وعملاء لكن لا فريق داخلياً يديره باحتراف يومي.',
 'إدارة شهرية — أول شهر تأسيس',
 '["استراتيجية حساب لكل منصة: دور، جمهور، نبرة، وأعمدة محتوى","تقويم محتوى شهري تعتمده قبل التنفيذ","تصميم ونشر بالحجم المتفق (منشورات/قصص/ريلز)","إدارة تفاعل يومية: ردود ورسائل ضمن نطاق معتمد","تقرير شهري: نمو حقيقي وتفاعل وأفضل محتوى ولماذا"]'::jsonb,
 '[{"title":"تأسيس الشهر الأول","desc":"تدقيق الحسابات وتوحيد الهوية وأعمدة المحتوى — الأساس قبل الضخ"},{"title":"التقويم الشهري","desc":"شهر كامل مخطط تعتمده من بوابتك دفعة واحدة — لا مفاجآت يومية"},{"title":"الإنتاج والنشر","desc":"تصميم ونشر بأوقات جمهورك مع فحص جودة قبل كل نشر"},{"title":"التفاعل اليومي","desc":"ردود ضمن دليل معتمد — والحساس يُرفع لك فوراً"},{"title":"الدورة الشهرية","desc":"تقرير صادق ثم تقويم الشهر التالي بما تعلمناه"}]'::jsonb,
 '["وصول الحسابات (صلاحيات إدارة لا كلمات مرور بالرسائل)","مواد خام: صور منتجات/فروع، أخبارك، عروضك أولاً بأول","اعتماد التقويم الشهري خلال ٣ أيام عمل","دليل الردود: ماذا نقول في الحالات الحساسة"]'::jsonb,
 '["نمو المتابعين الحقيقيين (نستبعد الوهمي)","معدل التفاعل لكل منشور واتجاهه","زمن الرد على الرسائل والتعليقات","التحويلات من السوشال (زيارات، رسائل، طلبات)"]'::jsonb);

select public._sg('influencer-marketing',
 'مؤثرون يشبهون علامتك يتحدثون عنها بصدق: نختار بالأرقام لا بالشهرة، نتفاوض ونتعاقد ونراقب التنفيذ — ونقيس المبيعات لا الإعجابات.',
 'علامة منتجات أو خدمات جمهورها يثق بتوصيات المؤثرين (جمال، مطاعم، تقنية، عائلي) وتريد إنفاقاً محسوباً لا مجاملات.',
 '٣–٦ أسابيع للحملة الواحدة',
 '["قائمة مؤثرين مرشحة بالأرقام: جمهور حقيقي، تفاعل صادق، ملاءمة قيم","التفاوض والتعاقد بعقود تحفظ حقك (تسليمات، مواعيد، حقوق استخدام)","موجه إبداعي لكل مؤثر يحفظ رسالتك ويترك صوته","أكواد خصم/روابط تتبع لكل مؤثر — القياس بالمبيعات","تقرير حملة: تكلفة الوصول والتحويل لكل مؤثر — من يستحق التكرار"]'::jsonb,
 '[{"title":"معايير الاختيار","desc":"جمهور المؤثر الفعلي (فحص وهمي)، تفاعله الصادق، وتاريخه — قبل أي اسم"},{"title":"الترشيح والاعتماد","desc":"قائمة بأرقامها الكاملة تختار منها — القرار لك بالبيانات"},{"title":"التعاقد","desc":"عقود واضحة: التسليمات والمواعيد وحقوق إعادة الاستخدام"},{"title":"التنفيذ والمراقبة","desc":"موجه إبداعي، مراجعة قبل النشر حيث اتفق، وتوثيق كل نشر"},{"title":"القياس الصادق","desc":"كود وتتبع لكل مؤثر — التقرير بالمبيعات والتكلفة لا باللقطات"}]'::jsonb,
 '["الميزانية ونطاق الحملة","المنتج/الخدمة وعينات للمؤثرين","اعتماد القائمة والموجه الإبداعي","آلية أكواد الخصم من متجرك"]'::jsonb,
 '["تكلفة الوصول الحقيقي لكل مؤثر","المبيعات/الطلبات بكل كود وتتبع","التفاعل الصادق على المحتوى (تعليقات حقيقية)","تكلفة الاكتساب مقارنة بقنواتك الأخرى"]'::jsonb);

select public._sg('social-strategy',
 'قبل أن تنشر: لماذا وأين ولمن وبأي صوت؟ استراتيجية سوشال مكتوبة تحسم منصاتك وأعمدة محتواك وإيقاعك ومقاييسك — فيصير كل منشور خطوة في اتجاه واحد.',
 'منشأة تنشر بلا بوصلة أو تدخل السوشال لأول مرة وتريد أساساً قبل حرق الجهد.',
 '٣–٤ أسابيع',
 '["تحليل حضورك الحالي ومنافسيك بالأرقام","تعريف الجمهور: شرائح بأنماط استخدامها الفعلي للمنصات","خارطة المنصات: أين تتواجد وأين لا (وقول لا موثق)","أعمدة المحتوى ونِسَبها ونبرة الصوت بأمثلة","خطة إيقاع ومقاييس نجاح — وثيقة تنفذها أنت أو نحن"]'::jsonb,
 '[{"title":"التشخيص","desc":"حساباتك ومنافسوك بالأرقام: ما ينجح في سوقك فعلاً ولماذا"},{"title":"الجمهور","desc":"شرائحك ومنصاتها وأوقاتها وأسئلتها — من بيانات حقيقية"},{"title":"القرارات","desc":"المنصات والأعمدة والنبرة والإيقاع — ورشة اعتماد معك"},{"title":"الوثيقة","desc":"استراتيجية مكتوبة بأمثلة تطبيقية لكل عمود محتوى"},{"title":"التسليم","desc":"جلسة شرح لفريقك + شهر أسئلة مفتوح بعد التسليم"}]'::jsonb,
 '["وصول قراءة لحساباتك وأرقامها","أهدافك التجارية من السوشال بصراحة","من سينفذ: فريقك أم نحن (تحدد عمق التفصيل)"]'::jsonb,
 '["اكتمال الوثيقة واعتمادها","قابلية التنفيذ: فريقك يبدأ منها دون أسئلة أساسية","(بعد التطبيق بربع) اتجاه النمو والتفاعل مقابل خط الأساس"]'::jsonb);

select public._sg('community-management',
 'جمهورك ليس أرقاماً بل مجتمع: نديره باسمك — ردود بلهجة علامتك، احتواء الغضب قبل انتشاره، وتحويل الراضين سفراء — الثقة تُبنى في التعليقات لا المنشورات.',
 'علامة تفاعلها كثيف (تعليقات، رسائل، مجموعات) ولا تستطيع تركه بلا إدارة يومية محترفة.',
 'إدارة شهرية مستمرة',
 '["تغطية يومية بنافذة رد متفقة (ضمن ساعات العمل أو أوسع)","دليل ردود معتمد: النبرة، الحالات الشائعة، وخطوط التصعيد الحمراء","احتواء الشكاوى العلنية ونقلها لقنوات الحل وتوثيقها في نظامك","رصد ذكر علامتك خارج حساباتك والتدخل حيث يلزم","تقرير شهري: حجم التفاعل، أوقاته، مواضيعه، ومزاج الجمهور"]'::jsonb,
 '[{"title":"دليل الردود","desc":"نبنيه معك: الأسئلة الشائعة بأجوبتها، النبرة، وما يُرفع لك فوراً"},{"title":"التشغيل اليومي","desc":"تغطية بنافذة الرد المتفقة وتوثيق كل حالة حساسة"},{"title":"التصعيد المنضبط","desc":"الحساس والقانوني والغاضب جداً يصلك بقناة متفقة خلال دقائق"},{"title":"الرصد الخارجي","desc":"ذكر علامتك في المنصات العامة يُرصد ويُقيّم أسبوعياً"},{"title":"الدورة الشهرية","desc":"تقرير مزاج الجمهور ومواضيعه — إنذارك المبكر لمشاكل المنتج"}]'::jsonb,
 '["صلاحيات إدارة التعليقات والرسائل","اعتماد دليل الردود وحالات التصعيد","قناة تواصل سريعة للحالات الحساسة (مجموعة/جوال)"]'::jsonb,
 '["زمن الرد المتوسط ضمن النافذة المتفقة","نسبة الحالات المحلولة دون تصعيد","مزاج الجمهور شهرياً (إيجابي/محايد/سلبي)","شكاوى علنية تحولت حلاً موثقاً"]'::jsonb);

-- ---------- الهوية والتصميم الإبداعي -------------------------------------------
select public._sg('brand-strategy',
 'قبل الشعار والألوان: من أنت ولمن ولماذا يختارونك؟ استراتيجية علامة تحسم تموضعك ووعدك وشخصيتك وقصتك — الأساس الذي يجعل كل ما بعده متسقاً.',
 'منشأة جديدة تتأسس صح، أو قائمة تشعر أن صورتها مشوشة ولا تشبه حجمها الحقيقي.',
 '٤–٦ أسابيع',
 '["بحث: عملاؤك الحاليون (مقابلات)، منافسوك، وفجوة التموضع","التموضع: لمن أنت، ضد ماذا، ووعدك المميز بجملة تُحفظ","شخصية العلامة: قيم، نبرة، وقصة تأسيس تُروى","معمارية العلامة إن تعددت خدماتك/منتجاتك","وثيقة استراتيجية تُسلّم بورشة — مرجع كل قرار تسويقي بعدها"]'::jsonb,
 '[{"title":"الاستماع","desc":"مقابلات معك ومع عملائك الفعليين — لماذا اختاروك بكلماتهم هم"},{"title":"خريطة السوق","desc":"تموضع المنافسين ووعودهم — أين الزحام وأين الفراغ الصادق"},{"title":"ورشة التموضع","desc":"نعرض خيارات تموضع مدروسة وتُحسم معك في الغرفة"},{"title":"الصياغة","desc":"الوعد والشخصية والقصة والرسائل الأساسية مكتوبة بدقة"},{"title":"التسليم بورشة","desc":"شرح الوثيقة لفريقك وكيف تحكم بها كل قرار قادم"}]'::jsonb,
 '["وقتك الصادق: مقابلة عميقة معك ومع شريكك","تسهيل الوصول لـ٥ من عملائك للمقابلات","صراحة كاملة عن الأرقام والطموح — الاستراتيجية على الورد الكاذب تنكسر"]'::jsonb,
 '["وضوح التموضع: فريقك يقوله بجملة واحدة متطابقة","اعتماد الوثيقة كمرجع (نلاحظه في قراراتك بعدها)","(بعد ربعين) اتساق رسائلك عبر القنوات وتحسن استدعاء العلامة"]'::jsonb);

select public._sg('logo-identity',
 'شعار يُعرف من بعيد وهوية تعمل في كل مكان: من بطاقة العمل إلى لوحة المحل إلى أيقونة التطبيق — تصميم مبني على استراتيجيتك لا على موضة تنتهي.',
 'منشأة تتأسس أو تعيد إطلاق نفسها وتريد وجهاً بصرياً يليق بمستواها ويثبت سنوات.',
 '٣–٥ أسابيع',
 '["٣ اتجاهات تصميم مبنية على موجه إبداعي معتمد","الشعار النهائي بصيغه كاملة (طباعة، شاشة، تطبيقات، أحادي اللون)","منظومة الألوان والخطوط العربية/اللاتينية المرخصة","تطبيقات أساسية: بطاقة، ترويسة، توقيع بريد، غلاف سوشال","ملف تسليم منظم بكل الصيغ + حقوق ملكية كاملة لك بعد السداد"]'::jsonb,
 '[{"title":"الموجه الإبداعي","desc":"من استراتيجيتك أو جلسة مكثفة: الشخصية والجمهور والمشاعر المستهدفة"},{"title":"الاتجاهات","desc":"٣ اتجاهات حقيقية مختلفة الفلسفة — لا نسخة واحدة بثلاثة ألوان"},{"title":"التطوير","desc":"الاتجاه المختار يُصقل: توازن، اختبار مقاسات، أحادي، خلفيات"},{"title":"التطبيقات","desc":"الهوية على موادك الفعلية لتراها حية قبل الاعتماد"},{"title":"التسليم","desc":"كل الصيغ منظمة بدليل استخدام مصغر"}]'::jsonb,
 '["استراتيجية علامتك إن وجدت (وإلا نبدأ بجلسة تأسيس)","أمثلة هويات تعجبك وأخرى تنفر منها","قرار مجمع من الشركاء في محطات الاعتماد — لجنة التصميم تقتل التصميم"]'::jsonb,
 '["اعتماد الاتجاه خلال جولتي عرض","عمل الشعار بكل المقاسات والخلفيات المختبرة","تسليم كامل الصيغ بلا رجوع لاحق لملفات ناقصة"]'::jsonb);

select public._sg('brand-guidelines',
 'هويتك محمية من العبث: دليل استخدام يحسم كل سؤال — مساحات الشعار، درجات الألوان، الخطوط، الصور، والنبرة — فيصمم أي مصمم في العالم باسمك دون أن يفسدها.',
 'علامة لديها شعار وهوية لكن كل مصمم يتصرف فيها على مزاجه — أو تستعد للتوسع وتريد ضبطاً قبل التفلت.',
 'أسبوعان إلى أربعة',
 '["دليل هوية شامل PDF منظم الفصول","قواعد الشعار: مساحات، مقاسات دنيا، استخدامات ممنوعة بأمثلة","نظام الألوان بأكواده الكاملة (طباعة وشاشة) والخطوط ببدائلها","اتجاه الصور والرسوم: ما يشبهك وما لا","نبرة الصوت كتابةً بأمثلة عربية فعلية"]'::jsonb,
 '[{"title":"جرد الموجود","desc":"جمع كل استخدامات هويتك الحالية — الملتزم والمخالف"},{"title":"تقنين القواعد","desc":"تحويل الممارسات الصحيحة قواعد مكتوبة وسد الفجوات"},{"title":"أمثلة الصح والخطأ","desc":"كل قاعدة بمثال ملتزم وآخر مخالف — الدليل الجيد يُفهم بالنظر"},{"title":"المراجعة","desc":"جولة اعتماد معك ومع من يستخدم الهوية يومياً"},{"title":"التسليم","desc":"PDF نهائي + ملفات الأصول منظمة للتوزيع"}]'::jsonb,
 '["ملفات هويتك المصدرية (شعار، ألوان، خطوط)","أمثلة استخدامات سابقة أعجبتك وأخرى أزعجتك","تراخيص الخطوط إن وجدت"]'::jsonb,
 '["إجابة الدليل عن أسئلة الاستخدام اليومية دون رجوع لنا","التزام الموردين الجدد به من أول تسليم","اكتمال الأصول: لا أحد يطلب ملفاً ناقصاً بعده"]'::jsonb);

select public._sg('motion-graphics',
 'أفكارك تتحرك: فيديوهات موشن جرافيك تشرح خدمتك المعقدة في دقيقة، وتفتتح حساباتك بمقدمات تليق — سيناريو، رسم، تحريك، وصوت بجودة تعرض بها أمام أي أحد.',
 'منشأة تحتاج شرح خدمة/منتج معقد ببساطة، أو محتوى فيديو منتظماً بهوية متحركة ثابتة.',
 '٢–٤ أسابيع للفيديو الواحد بحسب مدته وتعقيده',
 '["سيناريو ونص تعليق معتمدان قبل أي رسم","لوحة قصة (Storyboard) بالمشاهد الرئيسية","التصميم والتحريك بهوية علامتك","تعليق صوتي احترافي وموسيقى مرخصة وهندسة صوت","الملف النهائي بمقاسات منصاتك + ملفات المشروع محفوظة لتحديثات مستقبلية"]'::jsonb,
 '[{"title":"السيناريو","desc":"الرسالة الواحدة والقصة — نكتب ونعتمد النص قبل أي إنتاج، تغيير النص بعد التحريك مكلف"},{"title":"لوحة القصة","desc":"المشاهد مرسومة مبدئياً لتعتمد الإيقاع والاتجاه"},{"title":"التصميم","desc":"إطارات المشاهد النهائية بألوانك وشخصياتك"},{"title":"التحريك والصوت","desc":"تحريك احترافي + تعليق مرخّص + موسيقى وهندسة"},{"title":"التسليم","desc":"جولة تعديلات ضمن النطاق ثم التصدير بكل المقاسات"}]'::jsonb,
 '["الرسالة الأساسية للفيديو ومدة مستهدفة","هويتك البصرية","اعتماد السيناريو ولوحة القصة في محطتيهما (تعديل ما بعدهما خارج النطاق)"]'::jsonb,
 '["اعتماد من محطتي السيناريو واللوحة دون تجاوز","نسبة إكمال المشاهدة عند النشر","الفهم: جمهورك يشرح خدمتك بعد المشاهدة (نختبرها)"]'::jsonb);

select public._sg('packaging-print',
 'منتجك على الرف له ثلاث ثوانٍ ليُلتقط: تصميم تغليف ومطبوعات يوقف العين ويحكي علامتك — مضبوط فنياً للطباعة الفعلية بلا مفاجآت ألوان أو قصّ.',
 'منتجات تُعرض على أرفف أو تُشحن بصناديق، ومنشآت تحتاج مطبوعات مؤسسية (بروشورات، ملفات، لافتات).',
 '٢–٤ أسابيع + دورة الطباعة',
 '["تصميم التغليف/المطبوعة بهوية علامتك ومتطلبات التموضع","ملفات طباعة نهائية مضبوطة (CMYK، قصّ، تسليخ) جاهزة لأي مطبعة","التزام بمتطلبات البيانات النظامية للمنتجات (مكونات، باركود، بلد المنشأ)","بروفة طباعة رقمية/فعلية قبل الكمية","إشراف اختياري على الطباعة مع المطبعة"]'::jsonb,
 '[{"title":"موجه التصميم","desc":"المنتج، الرف، المنافسون بجواره، والمعلومة الأهم التي يجب أن تُقرأ أولاً"},{"title":"الاتجاهات","desc":"اتجاهان إلى ثلاثة على شكل المنتج الفعلي (موك أب واقعي)"},{"title":"الضبط الفني","desc":"قوالب القص والطي وألوان الطباعة — حيث تموت التصاميم الجميلة عادة"},{"title":"البروفة","desc":"بروفة معتمدة منك قبل أمر الكمية — القاعدة الذهبية"},{"title":"التسليم/الإشراف","desc":"ملفات نهائية للمطبعة وإشراف على أول تشغيلة إن طلبت"}]'::jsonb,
 '["مقاسات وخامات المنتج/المطبوعة (أو نأخذها مع المطبعة)","النصوص والبيانات النظامية كاملة","اعتماد البروفة قبل الطباعة الكمية"]'::jsonb,
 '["مطابقة المطبوع النهائي للبروفة المعتمدة","صفر إعادة طباعة بسبب ملفاتنا","(للتغليف) ملاحظة أثر الرف: التقاط العين والتقاط اليد"]'::jsonb);

-- ---------- الويب والمنتجات الرقمية --------------------------------------------
select public._sg('websites',
 'موقع يليق بعلامتك ويعمل لها: سريع، عربي أولاً، متجاوب، محسّن للبحث من يومه الأول — ومبني ليقود الزائر نحو فعل واحد واضح لا ليكون بروشوراً صامتاً.',
 'منشأة بلا موقع، أو موقعها القديم بطيء/غير متجاوب/لا يعكس مستواها الحالي.',
 '٤–٨ أسابيع بحسب عدد الصفحات والوظائف',
 '["هيكل موقع ورحلة زائر معتمدان قبل التصميم","تصميم واجهات بهوية علامتك (جوال أولاً)","تطوير سريع الأداء بمعايير Core Web Vitals","أساس سيو كامل: بنية، سرعة، بيانات منظمة، وربط Search Console","لوحة إدارة محتوى تحدث بها بنفسك + تدريب","شهر دعم فني بعد الإطلاق — والدومين والاستضافة باسمك دائماً"]'::jsonb,
 '[{"title":"الهيكل والرحلة","desc":"صفحات الموقع ووظيفة كل واحدة والفعل المطلوب من الزائر — خريطة تُعتمد قبل أي بكسل"},{"title":"التصميم","desc":"واجهات الصفحات الرئيسية للاعتماد ثم البقية على نفس النظام"},{"title":"التطوير","desc":"بناء سريع متجاوب على بيئة تجريبية تشاهدها أولاً بأول"},{"title":"المحتوى والسيو","desc":"رفع المحتوى بهيكلة بحث صحيحة وبيانات منظمة"},{"title":"الفحص والإطلاق","desc":"فحص إطلاق شامل: سرعة، أجهزة، نماذج، تتبع — ثم التحويل للدومين"},{"title":"التسليم والتدريب","desc":"تدريب على لوحة الإدارة + شهر دعم لما بعد الإطلاق"}]'::jsonb,
 '["المحتوى النصي والصور (أو أضف خدمات المحتوى والتصوير)","وصول الدومين أو شراؤه باسمك","اعتماد الهيكل ثم التصميم في محطتيهما","تعريف هدف الموقع الأول: اتصال؟ طلب؟ حجز؟"]'::jsonb,
 '["سرعة التحميل (نتائج PageSpeed موثقة عند التسليم)","التحويلات: نسبة الزوار المنفذين للفعل المستهدف","الفهرسة الكاملة في جوجل خلال أسبوعين","استقلاليتك: تحديث المحتوى بنفسك دون رجوع لنا"]'::jsonb);

select public._sg('ecommerce',
 'متجر إلكتروني يبيع فعلاً: تجربة شراء سلسة بالجوال، بوابات دفع سعودية، شحن مربوط، وتهيئة كاملة للطلب الأول — مبني على منصة تناسب حجمك لا أكبر فاتورة.',
 'تاجر يبدأ البيع أونلاين أو ينتقل من منصة ضاق بها — ويريد متجراً يديره بنفسه بعد التسليم.',
 '٤–٨ أسابيع بحسب حجم الكتالوج',
 '["اختيار منصة مبرر بالأرقام (سلة/زد/شوبيفاي/مخصص) لحجمك وخططك","تصميم متجر بهويتك بتجربة شراء جوال أولاً","رفع وتنظيم الكتالوج بأوصاف تبيع وصور مرتبة","ربط الدفع (مدى، Apple Pay، تمارا/تابي حسب رغبتك) والشحن والفواتير","تهيئة سيو المتجر وتتبع التحويل للإعلانات القادمة","تدريب كامل على الإدارة + شهر دعم"]'::jsonb,
 '[{"title":"جلسة التأسيس","desc":"منتجاتك، هوامشك، شحنك، وخططك — لنختار المنصة الصح لا الأشهر"},{"title":"البناء والتصميم","desc":"تجهيز المتجر بهويتك وتجربة شراء مختصرة الخطوات"},{"title":"الكتالوج","desc":"رفع المنتجات بأوصاف مقنعة وتصنيف يسهل التصفح"},{"title":"الربط المالي واللوجستي","desc":"بوابات الدفع وشركات الشحن والفوترة — باختبارات شراء فعلية"},{"title":"فحص الإطلاق","desc":"طلبات تجريبية كاملة من التصفح للدفع للشحن — قبل أول عميل حقيقي"},{"title":"التسليم","desc":"تدريبك على الطلبات والمخزون والعروض + شهر دعم"}]'::jsonb,
 '["صور المنتجات وبياناتها (أو أضف خدمة التصوير)","السجل التجاري وحسابك البنكي لبوابات الدفع","سياسات الشحن والاسترجاع (نساعدك بصياغتها)","اعتماد المنصة قبل البناء"]'::jsonb,
 '["إتمام الشراء: نسبة من أضاف للسلة وأكمل الدفع","سرعة المتجر بالجوال","صفر أخطاء دفع/شحن في أسبوع الإطلاق الأول","استقلاليتك بإدارة الطلبات من اليوم الأول"]'::jsonb);

select public._sg('ux-design',
 'واجهات تطبيق يفهمها المستخدم من أول نظرة: بحث مستخدمين حقيقي، رحلات مرسومة، ونماذج تفاعلية تُختبر قبل أن يكتب مطورك سطراً — التصميم الصح يوفر شهور تطوير.',
 'منشأة تبني تطبيقاً أو منتجاً رقمياً وتريد واجهاته مصممة على فهم المستخدم لا على ذوق الاجتماع.',
 '٣–٦ أسابيع بحسب عدد الشاشات',
 '["بحث مستخدمين: مقابلات/اختبارات مع مستخدمين فعليين من جمهورك","رحلات المستخدم وتدفقات الشاشات معتمدة","تصميم واجهات كامل بنظام مكونات (Design System) قابل للتوسع","نموذج تفاعلي (Prototype) يُختبر بمستخدمين قبل التطوير","ملفات تسليم مطورين منظمة (Figma) بكل الحالات والمقاسات"]'::jsonb,
 '[{"title":"فهم المستخدم","desc":"مقابلات ومهام مراقبة مع مستخدمين من جمهورك الفعلي — لا افتراضات غرف الاجتماعات"},{"title":"الرحلات والتدفقات","desc":"رسم مسارات المستخدم لكل هدف واعتمادها قبل الواجهات"},{"title":"التصميم","desc":"شاشات كاملة بنظام مكونات موحد يسهل تطويره وتوسيعه"},{"title":"الاختبار","desc":"نموذج تفاعلي يجرب عليه مستخدمون حقيقيون — نصلح الالتباس قبل التطوير"},{"title":"تسليم المطورين","desc":"ملفات منظمة بكل الحالات (فارغ، خطأ, تحميل) وجلسة تسليم مع فريقك التقني"}]'::jsonb,
 '["وصف المنتج وجمهوره وحالات الاستخدام الأساسية","تسهيل الوصول لـ٥ مستخدمين للاختبار","فريقك التقني في جلسة التسليم"]'::jsonb,
 '["نجاح مهام الاختبار: نسبة إكمال المستخدمين للمهام دون مساعدة","اعتماد التدفقات دون إعادة تصميم جوهرية أثناء التطوير","أسئلة المطورين بعد التسليم (القليل = ملفات واضحة)"]'::jsonb);

select public._sg('landing-pages',
 'صفحة هبوط لهدف واحد: تستقبل نقرة الإعلان وتحولها طلباً — رسالة مطابقة للإعلان، إقناع مرتب، ونموذج لا يهرب منه أحد. ومع اختبارات A/B تعرف أي نسخة تكسب فعلاً.',
 'حملة إعلانية توجه زيارات لصفحة رئيسية عامة فتتسرب — أو عرض جديد يستحق صفحة قناص.',
 'أسبوع إلى أسبوعين للصفحة الأولى',
 '["صفحة هبوط كاملة: نص إقناع + تصميم + تطوير سريع التحميل","تطابق الرسالة مع الإعلان (البند الأول في جودة الحملات)","نموذج/فعل واحد واضح بأقل حقول ممكنة (بجوال إلزامي)","تتبع تحويل مثبت + ربط ببكسلات منصاتك","نسخة B للاختبار عند الطلب + توصيات من نتائجه"]'::jsonb,
 '[{"title":"هدف الصفحة","desc":"الفعل الواحد المطلوب والجمهور القادم ومن أي إعلان — الصفحة بلا هدف واحد صفحة ضائعة"},{"title":"هيكل الإقناع","desc":"العنوان المطابق للإعلان، الدليل، الاعتراضات، والدعوة — نصاً معتمداً"},{"title":"التصميم والتطوير","desc":"بناء سريع جوال أولاً بلا تشتيتات (قائمة، روابط خارجة)"},{"title":"القياس","desc":"تحويل مثبت يعمل وبكسلات مربوطة — قبل استقبال أول نقرة"},{"title":"الاختبار","desc":"نسخة B على فرضية واحدة واضحة والقرار بالدلالة الإحصائية"}]'::jsonb,
 '["تفاصيل العرض والإعلانات التي ستقود لها","أي إثباتات: شهادات، أرقام، شعارات عملاء","وجهة الطلبات: بريد؟ واتساب؟ نظامك؟"]'::jsonb,
 '["معدل تحويل الصفحة (زائر ← طلب)","تطابق الرسالة: معدل الارتداد من إعلاناتها","سرعة التحميل بالجوال","نتائج اختبار A/B الموثقة إن فُعّل"]'::jsonb);

-- ---------- الاستراتيجية والاستشارات -------------------------------------------
select public._sg('marketing-strategy',
 'خطة تسويق سنوية تُنفذ لا تُعلّق: تشخيص صادق لوضعك، أهداف رقمية، خلطة قنوات مبررة بالميزانية، وتقويم ربع سنوي — فتعرف كل ريال أين يذهب ولماذا.',
 'منشأة تصرف على التسويق بلا خطة جامعة، أو تدخل سنة/مرحلة جديدة وتريد بوصلة معتمدة.',
 '٤–٦ أسابيع',
 '["تشخيص شامل: سوقك، منافسوك، قنواتك الحالية بأرقامها","أهداف سنوية رقمية مربوطة بأهداف عملك (لا أهداف تفاعل فارغة)","خلطة القنوات بميزانياتها المبررة: لماذا هذه الحصة هنا","تقويم مبادرات ربع سنوي بمسؤول ومؤشر لكل مبادرة","نموذج قياس موحد: التقرير الشهري الذي يحكم الخطة"]'::jsonb,
 '[{"title":"التشخيص","desc":"أرقامك الفعلية وقنواتك ومنافسوك — نبدأ من الواقع لا من الأمنيات"},{"title":"الأهداف","desc":"ترجمة أهداف عملك (إيراد، عملاء) أهدافاً تسويقية رقمية قابلة للمساءلة"},{"title":"الخلطة والميزانية","desc":"توزيع مبرر بالبيانات على القنوات — وقول لا صريح لقنوات لا تناسبك"},{"title":"التقويم","desc":"مبادرات كل ربع بمسؤولها ومؤشرها وتبعياتها"},{"title":"التسليم والمواكبة","desc":"ورشة تسليم + مراجعة ربع سنوية أولى معنا مضمنة"}]'::jsonb,
 '["أرقامك بصدق: مبيعات، هوامش، مصادر عملائك الحالية","وصول قراءة لحساباتك وأدواتك التسويقية","حضور الشركاء ورشة الأهداف — الخطة بلا التزامكم ورق"]'::jsonb,
 '["اعتماد الخطة وبدء تنفيذ الربع الأول خلال أسبوعين من التسليم","التزام المراجعة الربعية بالنموذج الموحد","(بعد سنة) تحقق الأهداف الرقمية أو تصحيح موثق لمسارها"]'::jsonb);

select public._sg('transformation-consulting',
 'أين يدخل الذكاء الاصطناعي منشأتك فعلاً؟ نمسح عملياتك، نرتب الفرص بالعائد والجهد، وننفذ معك أول انتصار سريع — تحول رقمي يبدأ بنتيجة لا بعرض تقديمي.',
 'منشأة تسمع ضجيج الذكاء وتريد قراراً هادئاً: ماذا يناسبنا نحن، بأي ترتيب، وبأي كلفة واقعية.',
 '٣–٥ أسابيع للتشخيص وخارطة الطريق',
 '["مسح عمليات شامل: أين الوقت يُصرف وأين الأخطاء تتكرر","خارطة فرص الأتمتة والذكاء مرتبة بمصفوفة عائد/جهد","خارطة طريق تنفيذ واقعية بمراحل وكلف تقديرية","تحديد «الانتصار السريع» الأول وتنفيذه ضمن النطاق حيث اتفق","جلسة توعية لفريقك: ما الذكاء وما ليس به — بلا تهويل"]'::jsonb,
 '[{"title":"مسح العمليات","desc":"جلسات مع أقسامك: ماذا يفعلون يومياً وأين يتسرب الوقت"},{"title":"مصفوفة الفرص","desc":"كل فرصة أتمتة بعائدها المتوقع وجهدها — الترتيب بالأرقام"},{"title":"خارطة الطريق","desc":"مراحل واقعية: ماذا أولاً ولماذا وبأي كلفة تقديرية"},{"title":"الانتصار السريع","desc":"ننفذ أول فرصة عالية العائد قليلة الجهد — النتيجة تبني الثقة للبقية"},{"title":"التسليم","desc":"ورشة عرض للشركاء + توعية للفريق"}]'::jsonb,
 '["وصول لجلسات مع رؤساء أقسامك","صراحة عن أدواتك وأنظمتك الحالية","قرار شريك حاضر في ورشة الأولويات"]'::jsonb,
 '["خارطة معتمدة ببنود مرتبة ومكلفة تقديرياً","الانتصار السريع منفذاً بأثر مقاس (ساعات موفرة/أخطاء منخفضة)","وضوح الفريق: يعرف ماذا سيتغير في عمله وماذا لا"]'::jsonb);

select public._sg('market-research',
 'قرارك الكبير يستحق بيانات: دراسة سوق ميدانية ورقمية — حجم الفرصة، منافسوك بالتفصيل، وصوت عميلك المستهدف بمقابلات واستبيانات حقيقية — قبل أن تستثمر لا بعده.',
 'منشأة أمام قرار دخول سوق/إطلاق منتج/توسع وتريد أرضية أرقام بدل رهان الحدس.',
 '٤–٨ أسابيع بحسب عمق الميدان',
 '["تقدير حجم السوق والفرصة بمنهجية موثقة المصادر","خريطة منافسين تفصيلية: عروض، أسعار، حصص تقديرية، ونقاط ضعف","بحث ميداني: استبيان بعينة ممثلة و/أو مقابلات معمقة","تحليل سلوك البحث والطلب الرقمي في السعودية","تقرير قرار: التوصية وسيناريوهاتها — يُسلّم بورشة نقاش"]'::jsonb,
 '[{"title":"سؤال البحث","desc":"نحدد القرار المستهدف بدقة — البحث بلا سؤال محدد ينتج تقريراً سميناً بلا فائدة"},{"title":"البحث المكتبي","desc":"المصادر الرسمية (هيئة الإحصاء، التقارير القطاعية) وبيانات الطلب الرقمي"},{"title":"الميدان","desc":"استبيان مصمم بعناية و/أو مقابلات معمقة مع الجمهور المستهدف"},{"title":"التحليل","desc":"تقاطع المصادر واختبار الفرضيات — وما يناقض توقعاتك نقوله بوضوح"},{"title":"تقرير القرار","desc":"ورشة عرض: الأرقام، السيناريوهات، والتوصية المسببة"}]'::jsonb,
 '["القرار المطلوب دعمه بالبحث بصراحة","أي بيانات داخلية تفيد (مبيعات، استفسارات)","تسهيل وصول للعينة إن كان جمهورك متخصصاً"]'::jsonb,
 '["منهجية موثقة قابلة للمساءلة (حجم عينة، مصادر)","إجابة سؤال البحث بتوصية واضحة مسببة","قرارك متخذ على التقرير (نقيس ذلك بصراحة معك)"]'::jsonb);

-- ---------- العلاقات العامة والإعلام -------------------------------------------
select public._sg('pr-media-management',
 'حضورك في الإعلام يُدار لا يُترك للصدفة: قصص تستحق النشر تُصاغ وتُوزع على الصحف والمنصات المناسبة، وعلاقات صحفية تُبنى — وحين تأتي الأزمة تجدنا قبلها.',
 'منشأة لها قصة تستحق (توسع، إنجاز، مبادرة) أو تريد بناء حضور إعلامي مستمر يرفع ثقتها.',
 'حملة ٤–٦ أسابيع أو إدارة شهرية',
 '["استراتيجية رسائل إعلامية: قصصك التي تستحق ولمن تُروى","بيانات صحفية بمعايير النشر العربية وتوزيع على قوائم مستهدفة","بناء علاقات: ملفك التعريفي عند الصحفيين المعنيين بقطاعك","رصد التغطية وتقرير بما نُشر وقيمته","بروتوكول أزمة أساسي: من يتكلم وماذا يقول في أول ساعة"]'::jsonb,
 '[{"title":"القصص","desc":"نستخرج من منشأتك ما يستحق النشر فعلاً — الإعلام يريد قصة لا إعلاناً مجانياً"},{"title":"الصياغة","desc":"بيانات ومواد صحفية جاهزة النشر تحترم وقت المحرر"},{"title":"التوزيع المستهدف","desc":"قوائم صحفيي قطاعك بالاسم — لا رش جماعي يذهب للمهملات"},{"title":"المتابعة والرصد","desc":"متابعة شخصية ورصد كل نشر وتقييم قيمته"},{"title":"بروتوكول الأزمة","desc":"وثيقة مختصرة: المتحدث، الرسائل، وما لا يُقال — قبل أن تحتاجها"}]'::jsonb,
 '["قصصك وأخبارك أولاً بأول (نتفق على قناة سريعة)","متحدث رسمي متاح للصحفيين عند الطلب","اعتماد البيانات قبل التوزيع خلال يوم عمل"]'::jsonb,
 '["تغطيات منشورة: عددها ومكانتها (نوعية المنفذ)","قيمة التغطية الإعلانية المكافئة (AVE) كمؤشر استرشادي","نمو البحث عن اسمك بعد الحملات","جاهزية الأزمة: بروتوكول معتمد ومُتدرب عليه"]'::jsonb);

select public._sg('media-buying',
 'شراء إعلامي بعقلية مستثمر: لوحات طرق، إذاعة، رعايات، ومنصات كبرى — نفاوض بالأرقام، نوثق بعقود، ونقيس الأثر — فلا تدفع سعر اللوحة وهي فاضية نصف السنة.',
 'علامة تريد حضوراً واسعاً خارج الرقمي (افتتاح، وعي مدينة، موسم) بميزانية تستحق تفاوضاً محترفاً.',
 '٣–٥ أسابيع للتخطيط والتعاقد',
 '["خطة شراء: المنافذ والمواقع والتوقيتات بجمهور كل منها","تفاوض وتوثيق: أسعار مرجعية وعقود تحفظ حقك (مواقع، مدد، صيانة)","تنسيق المواد الإبداعية بمقاسات كل منفذ","إثباتات النشر: صور وتقارير تشغيل لكل موقع","تقرير أثر: بحث الاسم، الزيارات، والإشارات خلال فترة الحملة"]'::jsonb,
 '[{"title":"خطة الوصول","desc":"أين جمهورك فعلاً: مسارات الطرق، الأحياء، التوقيتات — بالبيانات المتاحة"},{"title":"التفاوض","desc":"عروض من أكثر من مورد وأسعار مرجعية — قاعدة عرضي السعر تعمل لصالحك"},{"title":"التعاقد","desc":"عقود بمواقع محددة بالصور ومدد وبنود صيانة وتعويض"},{"title":"التنفيذ","desc":"تسليم المواد ومتابعة التركيب بإثباتات موثقة"},{"title":"القياس","desc":"مؤشرات الأثر غير المباشر: بحث الاسم والزيارات في فترة الحملة"}]'::jsonb,
 '["الميزانية والمدن والفترة","هويتك ومواد الحملة (أو أضف خدمات التصميم)","اعتماد الخطة والعقود قبل الالتزام"]'::jsonb,
 '["كلفة الوصول التقديرية مقابل أسعار السوق (وفر التفاوض موثق)","إثباتات نشر كاملة لكل موقع متعاقد","أثر الحملة: بحث الاسم والإشارات خلال فترتها"]'::jsonb);

select public._sg('event-marketing',
 'فعاليتك تستحق جمهوراً ممتلئاً وأثراً يبقى بعدها: تسويق قبل (حضور)، وأثناء (تغطية)، وبعد (محتوى يعيش أشهراً) — الفعالية بلا تسويق قاعة فاضية.',
 'منشأة تقيم إطلاقاً/مؤتمراً/معرضاً أو تشارك بجناح وتريد أقصى عائد من كل ريال صُرف على الحدث.',
 '٤–٨ أسابيع قبل الفعالية + أسبوعان بعدها',
 '["خطة تسويق الحدث: الجمهور، قنوات الدعوة، وهدف حضور رقمي","هوية الفعالية وموادها (دعوات، شاشات، مطبوعات الجناح)","حملة حضور: إعلانات ودعوات ومؤثرون بحسب الجمهور","تغطية يوم الحدث: تصوير وبث لحظي على قنواتك","حصاد ما بعد الحدث: فيديو ملخص ومحتوى وتقرير أثر كامل"]'::jsonb,
 '[{"title":"هدف الحدث","desc":"نجاح الفعالية رقم: كم حاضراً، من هم، وماذا نريد منهم بعدها"},{"title":"الهوية والمواد","desc":"مظهر موحد من الدعوة إلى الشاشة إلى الجناح"},{"title":"حملة الحضور","desc":"دعوات مستهدفة وإعلانات وتسجيل يُدار — بمتابعة أرقام أسبوعية"},{"title":"يوم الحدث","desc":"تغطية مباشرة وتصوير احترافي — الحدث يحدث مرة ويُوثق للأبد"},{"title":"الحصاد","desc":"محتوى ما بعد الحدث ومتابعة المهتمين المسجلين وتقرير الأثر"}]'::jsonb,
 '["تفاصيل الفعالية: مكان، تاريخ، سعة، ميزانية","قوائم المدعوين المستهدفين إن وجدت","صلاحيات التصوير في الموقع"]'::jsonb,
 '["الحضور الفعلي مقابل الهدف والتسجيلات","المهتمون الملتقطون من الحدث (بيانات تواصل)","وصول محتوى التغطية والحصاد","أثر ما بعد الحدث: اجتماعات/طلبات نتجت عنه"]'::jsonb);

-- ---------- الإنتاج والخدمات المساندة ------------------------------------------
select public._sg('photography',
 'صورك سفيرة علامتك: تصوير احترافي لمنتجاتك وفريقك ومقراتك بإضاءة وإخراج يليقان — مكتبة صور تملكها وتستعملها في كل قنواتك بدل صور الأرشيف الأجنبية.',
 'منشأة تعتمد على صور جوال أو مواقع أرشيف ولا تملك مكتبة صور حقيقية باسمها.',
 'يوم إلى ثلاثة أيام تصوير + أسبوع معالجة',
 '["جلسة تصوير مخططة بقائمة لقطات معتمدة مسبقاً","صور معالجة بجودة نشر (ويب وطباعة) بدرجات ألوان هويتك","مكتبة منظمة مسماة جاهزة للفريق","حقوق استخدام كاملة لك بلا قيود","نسخ مقصوصة بمقاسات منصاتك الأساسية"]'::jsonb,
 '[{"title":"قائمة اللقطات","desc":"نخطط كل لقطة قبل يوم التصوير: المنتجات، الزوايا، الأجواء — يوم التصوير للتنفيذ لا للتفكير"},{"title":"التجهيز","desc":"الموقع والإضاءة والإكسسوارات — وتنسيق حضور من يلزم من فريقك"},{"title":"يوم التصوير","desc":"تنفيذ القائمة بانضباط مع مساحة لالتقاطات عفوية صادقة"},{"title":"الانتقاء والمعالجة","desc":"نرشح الأفضل ونعالجها بدرجات هويتك — لا فلاتر عشوائية"},{"title":"التسليم","desc":"مكتبة منظمة بكل المقاسات وحقوقها كاملة لك"}]'::jsonb,
 '["اعتماد قائمة اللقطات قبل الجلسة","جاهزية الموقع/المنتجات يوم التصوير","موافقات ظهور الأشخاص (نوفر نموذجاً)"]'::jsonb,
 '["تنفيذ قائمة اللقطات كاملة","التسليم في الموعد بالمقاسات المتفقة","استخدام المكتبة فعلياً في قنواتك (نتابعها معك)"]'::jsonb);

select public._sg('video-production',
 'فيديو يحكي قصتك بصدق سينمائي: إعلان، قصة علامة، أو تغطية — من الفكرة والسيناريو إلى التصوير بطاقم محترف — المحتوى المرئي أصل استثماري يخدمك سنوات.',
 'علامة تحتاج فيديو إعلانياً أو تعريفياً أو قصص عملاء — بجودة تعرض بثقة على أي شاشة.',
 '٣–٦ أسابيع من الفكرة للتسليم',
 '["معالجة إبداعية وسيناريو معتمدان قبل الإنتاج","تخطيط إنتاج كامل: مواقع، طاقم، معدات، تصاريح","يوم/أيام تصوير بطاقم ومعدات احترافية","اللقطات الخام محفوظة لك (أصل تستفيد منه لاحقاً)","الفيلم النهائي بعد المونتاج والتلوين والصوت + نسخ المنصات"]'::jsonb,
 '[{"title":"المعالجة الإبداعية","desc":"الفكرة والنبرة والمرجعيات البصرية — نتفق على الفيلم قبل تصويره"},{"title":"السيناريو والتخطيط","desc":"سيناريو مشهدي وخطة إنتاج: مواقع وطاقم وجدول ساعة بساعة"},{"title":"التصوير","desc":"تنفيذ منضبط بالجدول مع مخرج يحمي الرؤية المعتمدة"},{"title":"ما بعد الإنتاج","desc":"مونتاج وتلوين وصوت — بجولة تعديلات ضمن النطاق"},{"title":"التسليم","desc":"الفيلم بكل مقاسات منصاتك + الخام محفوظ باسمك"}]'::jsonb,
 '["اعتماد المعالجة والسيناريو في محطتيهما","تسهيل الوصول للمواقع والأشخاص الظاهرين","موافقات التصوير والتصاريح إن لزمت (نساعد باستخراجها)"]'::jsonb,
 '["الالتزام بجدول الإنتاج المعتمد","اعتماد الفيلم ضمن جولة التعديلات المتفقة","أداء الفيديو عند النشر: مشاهدة وإكمال وتحويل بحسب هدفه"]'::jsonb);

select public._sg('video-editing',
 'موادك الخام كنز مدفون: مونتاج احترافي يحولها أفلاماً وريلز تُشاهد للنهاية — إيقاع مشدود، تلوين موحد، صوت مضبوط، وترجمات — أنت تصور ونحن نصنع منها المحتوى.',
 'منشأة عندها مواد مصورة (فعاليات، جوال، مقابلات) أو تنتج ريلز دورية وتريد مونتاجاً يرفع مستواها.',
 'أيام للريلز — أسبوع إلى أسبوعين للأفلام',
 '["مونتاج بإيقاع مدروس لهدف كل مقطع ومنصته","تصحيح ألوان موحد وهوية جرافيك متحركة ثابتة (أسماء، شعارات)","معالجة صوت: تنقية، توازن، وموسيقى مرخصة","ترجمات/تعليقات نصية بقالب هويتك (أغلب المشاهدة صامتة)","نسخ بكل مقاسات المنصات + أرشفة مشروع قابلة للتعديل لاحقاً"]'::jsonb,
 '[{"title":"استلام المواد","desc":"قناة رفع منظمة وفرز سريع للصالح منها — ونصارحك إن كانت المادة لا تكفي"},{"title":"البنية","desc":"مخطط المقطع: البداية الخاطفة، التسلسل، والخاتمة بدعوة"},{"title":"المونتاج","desc":"قص بإيقاع، تلوين، جرافيك، وصوت — نسخة أولى للمراجعة"},{"title":"المراجعة","desc":"جولة تعديلات بملاحظات مجمعة ضمن النطاق"},{"title":"التسليم","desc":"كل المقاسات جاهزة النشر + المشروع مؤرشف"}]'::jsonb,
 '["المواد الخام بأعلى جودة متاحة (قناة رفع نوفرها)","هدف كل مقطع ومنصته","ملاحظات المراجعة مجمعة بجولة واحدة"]'::jsonb,
 '["زمن التسليم الملتزم لكل مقطع","نسبة إكمال المشاهدة بعد النشر","اعتماد من جولة التعديلات الواحدة","اتساق الهوية عبر كل المقاطع"]'::jsonb);

select public._sg('voice-over',
 'صوت يليق برسالتك: تعليق صوتي عربي احترافي بلهجات ونبرات تناسب كل غرض — من إعلان حماسي إلى شرح هادئ إلى رد آلي — مع هندسة صوت تجعله نقياً في أي سماعة.',
 'فيديوهات، إعلانات إذاعية، أنظمة رد آلي، أو محتوى تعليمي يحتاج صوتاً محترفاً لا تسجيل مكتب.',
 '٣ أيام إلى أسبوع بحسب الحجم',
 '["عينات أصوات مرشحة تختار منها (ذكر/أنثى، لهجة، نبرة)","تسجيل استوديو نقي بمعايير البث","هندسة صوت كاملة: تنقية، توازن، وتوقيت على الفيديو إن وجد","موسيقى ومؤثرات مرخصة عند الحاجة","الملفات بكل الصيغ المطلوبة وحقوق الاستخدام موثقة"]'::jsonb,
 '[{"title":"النص والتوجيه","desc":"مراجعة نصك (أو كتابته بخدمة الكتابة) وتحديد النبرة والإيقاع بمرجع صوتي"},{"title":"الترشيح","desc":"عينات من أصوات تناسب الغرض — تختار بأذنك"},{"title":"التسجيل","desc":"جلسة استوديو بتوجيه إخراجي — نسجل بدائل للجمل المفصلية"},{"title":"الهندسة","desc":"تنقية وموازنة ومزامنة مع الفيديو/النظام"},{"title":"التسليم","desc":"الصيغ كاملة + جولة تصحيح نطق ضمن النطاق"}]'::jsonb,
 '["النص النهائي معتمداً قبل التسجيل (تغييره بعده جلسة جديدة)","اللهجة والنبرة المطلوبة بمرجع إن أمكن","الغرض والقناة (يحدد المعايير التقنية)"]'::jsonb,
 '["اعتماد الصوت من الترشيحات الأولى","نقاء تقني بمعايير البث (بلا ضجيج أو صدى)","التسليم في الموعد بكل الصيغ"]'::jsonb);

select public._sg('ad-design',
 'مواد يومك الإعلانية بلا انتظار: بنرات، منشورات عروض، ستوريز، وإعلانات منصات — تصميم سريع ملتزم بهويتك حرفياً، بنظام طلبات واضح وتسليم بالموعد.',
 'منشأة تحتاج تدفقاً مستمراً من التصاميم اليومية (عروض، مناسبات، إعلانات) بجودة ثابتة وسرعة عملية.',
 'قطع خلال ٢–٣ أيام عمل — أو باقة شهرية بعدد قطع',
 '["تصاميم بهوية علامتك الموثقة (لا اجتهادات لونية)","كل المقاسات المطلوبة لكل قطعة (فيد، ستوري، بنر…)","ملفات مفتوحة عند طلبها لتعديلات مستقبلية","جولة تعديل لكل قطعة ضمن النطاق","التزام مواعيد موثق — العرض الموسمي المتأخر عرض ميت"]'::jsonb,
 '[{"title":"نظام الطلب","desc":"قناة طلبات واضحة: النص، الصور، المقاسات، والموعد — الطلب المكتمل يسلّم أسرع"},{"title":"التصميم","desc":"تنفيذ ملتزم بدليل هويتك مع لمسة إبداعية في إطارها"},{"title":"المراجعة","desc":"جولة تعديل بملاحظات مجمعة"},{"title":"التسليم","desc":"كل المقاسات جاهزة النشر في الموعد"}]'::jsonb,
 '["دليل هويتك (أو أضف خدمة بنائه أولاً)","نصوص وصور كل طلب كاملة","ملاحظات مجمعة بجولة واحدة لكل قطعة"]'::jsonb,
 '["الالتزام بمواعيد التسليم (نسبة موثقة شهرياً)","نسبة القطع المعتمدة من أول جولة","اتساق الهوية عبر كل ما نسلمه"]'::jsonb);

-- تنظيف الدالة المساعدة — بذور فقط
drop function public._sg(text, text, text, text, jsonb, jsonb, jsonb, jsonb);
